    // when the empirical rate alone already exceeds it.
    const mean = flips.reduce((a, b) => a + b, 0) / Math.max(1, flips.length);
    if (mean > alpha) {
      return { certified: false, looks, sampled: n };
    }
  }
  return {
    certified: false,
    looks,
    sampled: schedule[schedule.length - 1]!,
  };
}

